/// A regular ustar header and its payload location.
#[derive(Debug)]
pub struct Row {
    pub name: String,
    pub hdr: u64,
    pub size: u64,
    pub body: u64,
    pub flag: u8,
}

fn oct_u64(buf: &[u8]) -> Result<u64, i32> {
    let mut n = 0u64;
    let mut digit = false;
    for &b in buf {
        match b {
            0 | b' ' => {},
            b'0'..=b'7' => {
                digit = true;
                n = n.checked_mul(8).and_then(|x| x.checked_add(u64::from(b-b'0'))).ok_or(1)?;
            }
            _ => return Err(1),
        }
    }
    if digit { Ok(n) } else { Ok(0) }
}

pub fn scan(path: &str) -> Result<Vec<Row>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    let mut rows = Vec::new();
    let mut off = 0usize;
    let mut saw = false;
    loop {
        if off.checked_add(512).ok_or(1)? > raw.len() { return Err(1); }
        let blk = &raw[off..off+512];
        if blk.iter().all(|&b| b == 0) {
            // A valid stream ends with at least two complete zero blocks.
            if off.checked_add(1024).ok_or(1)? > raw.len()
                || raw[off..off+1024].iter().any(|&b| b != 0) { return Err(1); }
            if !saw || raw[off..].iter().any(|&b| b != 0) { return Err(1); }
            return Ok(rows);
        }
        if &blk[257..262] != b"ustar" { return Err(1); }
        saw = true;
        let nlen = blk[..100].iter().position(|&b| b == 0).unwrap_or(100);
        let name = std::str::from_utf8(&blk[..nlen]).map_err(|_| 1)?.to_string();
        if name.is_empty() { return Err(1); }
        let size = oct_u64(&blk[124..136])?;
        let body = off.checked_add(512).ok_or(1)?;
        let padded = size.checked_add(511).ok_or(1)? / 512 * 512;
        let next = (body as u64).checked_add(padded).ok_or(1)?;
        if next > raw.len() as u64 { return Err(1); }
        rows.push(Row { name, hdr: off as u64, size, body: body as u64, flag: blk[156] });
        off = next as usize;
    }
}

pub fn load_body(path: &str, row: &Row) -> Result<Vec<u8>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    let s = usize::try_from(row.body).map_err(|_| 1)?;
    let n = usize::try_from(row.size).map_err(|_| 1)?;
    let e = s.checked_add(n).ok_or(1)?;
    if e > raw.len() { return Err(1); }
    Ok(raw[s..e].to_vec())
