pub fn rib_b(a: &str, b: &str) -> Result<Pack, i32> {
    let sealed = std::fs::canonicalize("/app/sealwell").map_err(|_| 1)?;
    let archive = std::fs::canonicalize(a).map_err(|_| 1)?;
    if archive.parent() != Some(sealed.as_path()) { return Err(1); }

    let rows = hdr::scan(archive.to_str().ok_or(1)?)?;
    let regular: Vec<&hdr::Row> = rows.iter().filter(|r| r.flag == b'0' || r.flag == 0).collect();
    let recs = read_idx(b)?;
    if recs.len() != regular.len() { return Err(1); }
    for (x, r) in recs.iter().zip(regular.iter()) {
        if x.name != r.name || x.hdr != r.hdr || x.size != r.size || x.body != r.body { return Err(1); }
    }

    let mut t = String::new();
    let mut c = String::new();
    let mut events = Vec::new();
    let mut names = Vec::new();
    for r in regular.iter() {
        names.push(r.name.clone());
        let normalized = alias::fold(&r.name);
        let blob = hdr::load_body(archive.to_str().ok_or(1)?, r)?;
        if normalized == "etc/sys.conf" {
