        if normalized == "app.log" || normalized.ends_with("/app.log") {
            for line in String::from_utf8_lossy(&blob).lines() {
                let line = line.trim();
                if !line.is_empty() { events.push(line.to_string()); }
            }
        }
    }
    events.sort(); events.dedup();
    let source = archive.file_name().and_then(|x| x.to_str()).ok_or(1)?.to_string();
    Ok(Pack { t, c, e: events, n: regular.len() as u32, s: source, w: digest(&names.join("\n"))? })
}
